def clean(df):
    # Fix negative flipper length values
    df['flipper_length_mm'] = df['flipper_length_mm'].apply(lambda x: abs(x) if x < 0 else x)

    # Fix sex label variants
    df['sex'] = df['sex'].str.lower()

    return df

def answer(df):
    result = df.groupby('species')['flipper_length_mm'].mean().to_dict()
    return {k: round(v, 2) for k, v in result.items()}
